/**
* Generate Boost test fixtures on the shared inputs in `../inputs/`.
*
* ## Notes
*
* -   Run this script from the directory in which fixtures should be written.
* -   Inputs are read from the shared input files (`*.json`) with Boost.JSON, using its `precise` number parsing, so every value is parsed to the nearest double. `"NaN"`, `"Infinity"`, and `"-Infinity"` are mapped to the corresponding values. Each fixture's `meta.inputs` is the SHA-256 of the input file it read.
* -   Where Boost raises (`std::domain_error` below -1, and `std::overflow_error` at -1, under the default policy), the runner writes `null` for `expected`, and records the exception's type in a parallel `errors` array.
* -   For `double` arguments, `boost::math::log1p` checks the domain and pole itself and then returns `std::log1p( x )` (see `boost/math/special_functions/log1p.hpp`), so values are the C library's.
*/
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <float.h>
#include <time.h>
#include <dirent.h>
#include <math.h>
#include <stdexcept>
#include <string>
#include <vector>
#include <algorithm>
#include <boost/version.hpp>
#include <boost/math/special_functions/log1p.hpp>
#include <boost/json/src.hpp>
#ifdef __GLIBC__
#include <gnu/libc-version.h>
#endif

// Directory containing the shared inputs:
static const char *INPUTS = "../inputs";

/**
* Computes the SHA-256 digest of a byte array, as a lowercase hexadecimal string.
*
* @param data  bytes
* @param len   number of bytes
* @return      digest
*/
std::string sha256( const unsigned char *data, const size_t len ) {
	static const uint32_t K[ 64 ] = {
		0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
		0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
		0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
		0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
		0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
		0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
		0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
		0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
	};
	uint32_t h[ 8 ] = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 };
	std::vector<unsigned char> msg( data, data+len );
	uint64_t bits = (uint64_t)len * 8;
	uint32_t w[ 64 ];
	uint32_t a, b, c, d, e, f, g, k, t1, t2;
	size_t i;
	int j;
	char hex[ 65 ];

	msg.push_back( 0x80 );
	while ( msg.size() % 64 != 56 ) {
		msg.push_back( 0x00 );
	}
	for ( j = 7; j >= 0; j-- ) {
		msg.push_back( (unsigned char)( bits >> (j*8) ) );
	}
	#define ROTR( x, n ) ( ( (x) >> (n) ) | ( (x) << (32-(n)) ) )
	for ( i = 0; i < msg.size(); i += 64 ) {
		for ( j = 0; j < 16; j++ ) {
			w[ j ] = ( (uint32_t)msg[ i+(j*4) ] << 24 ) | ( (uint32_t)msg[ i+(j*4)+1 ] << 16 ) | ( (uint32_t)msg[ i+(j*4)+2 ] << 8 ) | (uint32_t)msg[ i+(j*4)+3 ];
		}
		for ( j = 16; j < 64; j++ ) {
			w[ j ] = w[ j-16 ] + ( ROTR( w[ j-15 ], 7 ) ^ ROTR( w[ j-15 ], 18 ) ^ ( w[ j-15 ] >> 3 ) ) + w[ j-7 ] + ( ROTR( w[ j-2 ], 17 ) ^ ROTR( w[ j-2 ], 19 ) ^ ( w[ j-2 ] >> 10 ) );
		}
		a = h[ 0 ]; b = h[ 1 ]; c = h[ 2 ]; d = h[ 3 ]; e = h[ 4 ]; f = h[ 5 ]; g = h[ 6 ]; k = h[ 7 ];
		for ( j = 0; j < 64; j++ ) {
			t1 = k + ( ROTR( e, 6 ) ^ ROTR( e, 11 ) ^ ROTR( e, 25 ) ) + ( ( e & f ) ^ ( ~e & g ) ) + K[ j ] + w[ j ];
			t2 = ( ROTR( a, 2 ) ^ ROTR( a, 13 ) ^ ROTR( a, 22 ) ) + ( ( a & b ) ^ ( a & c ) ^ ( b & c ) );
			k = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
		}
		h[ 0 ] += a; h[ 1 ] += b; h[ 2 ] += c; h[ 3 ] += d; h[ 4 ] += e; h[ 5 ] += f; h[ 6 ] += g; h[ 7 ] += k;
	}
	#undef ROTR
	for ( j = 0; j < 8; j++ ) {
		snprintf( hex+(j*8), 9, "%08x", h[ j ] );
	}
	return std::string( hex );
}

/**
* Writes a double to a file as a JSON value, matching the shared input files.
*
* @param f  file to write to
* @param x  value
*/
void write_f64( FILE *f, const double x ) {
	if ( x != x ) {
		fprintf( f, "\"NaN\"" );
	} else if ( x == HUGE_VAL ) {
		fprintf( f, "\"Infinity\"" );
	} else if ( x == -HUGE_VAL ) {
		fprintf( f, "\"-Infinity\"" );
	} else {
		fprintf( f, "%.17g", x );
	}
}

/**
* Reads a shared input file's values.
*
* @param bytes  file contents
* @param path   file path, for error messages
* @return       input values
*/
std::vector<double> read_inputs( const std::string &bytes, const std::string &path ) {
	boost::json::parse_options opts;
	std::vector<double> x;
	boost::json::value doc;
	size_t i;

	opts.numbers = boost::json::number_precision::precise;
	try {
		doc = boost::json::parse( bytes, boost::json::storage_ptr(), opts );
	} catch ( std::exception &e ) {
		fprintf( stderr, "%s: %s\n", path.c_str(), e.what() );
		exit( 1 );
	}
	const boost::json::array &arr = doc.as_object().at( "x" ).as_array();
	for ( i = 0; i < arr.size(); i++ ) {
		if ( arr[ i ].is_string() ) {
			const boost::json::string &str = arr[ i ].as_string();
			if ( str == "NaN" ) {
				x.push_back( NAN );
			} else if ( str == "Infinity" ) {
				x.push_back( HUGE_VAL );
			} else if ( str == "-Infinity" ) {
				x.push_back( -HUGE_VAL );
			} else {
				fprintf( stderr, "%s: unexpected string at element %zu\n", path.c_str(), i );
				exit( 1 );
			}
		} else {
			x.push_back( arr[ i ].to_number<double>() );
		}
	}
	return x;
}

/**
* Reads a shared input file, and writes fixtures to a JSON file of the same name.
*
* @param name  input filename (`<regime>.json`)
*/
void gen( const std::string &name ) {
	std::string regime = name.substr( 0, name.size()-5 );
	std::string inpath = std::string( INPUTS ) + "/" + name;
	std::string outpath = name;
	std::string bytes;
	std::vector<double> x;
	std::vector<double> y;
	std::vector<std::string> errors;
	char buf[ 4096 ];
	bool any = false;
	size_t n;
	size_t i;
	FILE *f;
	char ts[ 32 ];
	time_t now;

	f = fopen( inpath.c_str(), "rb" );
	if ( f == NULL ) {
		fprintf( stderr, "unable to open %s\n", inpath.c_str() );
		exit( 1 );
	}
	while ( ( n = fread( buf, 1, sizeof( buf ), f ) ) > 0 ) {
		bytes.append( buf, n );
	}
	fclose( f );
	x = read_inputs( bytes, inpath );
	for ( i = 0; i < x.size(); i++ ) {
		try {
			y.push_back( boost::math::log1p( x[ i ] ) );
			errors.push_back( "" );
		} catch ( std::domain_error & ) {
			y.push_back( 0.0 );
			errors.push_back( "std::domain_error" );
			any = true;
		} catch ( std::overflow_error & ) {
			y.push_back( 0.0 );
			errors.push_back( "std::overflow_error" );
			any = true;
		}
	}

	now = time( NULL );
	strftime( ts, sizeof( ts ), "%Y-%m-%dT%H:%M:%SZ", gmtime( &now ) );

	f = fopen( outpath.c_str(), "w" );
	if ( f == NULL ) {
		fprintf( stderr, "unable to open %s\n", outpath.c_str() );
		exit( 1 );
	}
	fprintf( f, "{\"x\":[" );
	for ( i = 0; i < x.size(); i++ ) {
		if ( i > 0 ) {
			fprintf( f, "," );
		}
		write_f64( f, x[ i ] );
	}
	fprintf( f, "],\"expected\":[" );
	for ( i = 0; i < y.size(); i++ ) {
		if ( i > 0 ) {
			fprintf( f, "," );
		}
		if ( errors[ i ].empty() ) {
			write_f64( f, y[ i ] );
		} else {
			fprintf( f, "null" );
		}
	}
	fprintf( f, "]" );
	if ( any ) {
		fprintf( f, ",\"errors\":[" );
		for ( i = 0; i < errors.size(); i++ ) {
			if ( i > 0 ) {
				fprintf( f, "," );
			}
			if ( errors[ i ].empty() ) {
				fprintf( f, "null" );
			} else {
				fprintf( f, "\"%s\"", errors[ i ].c_str() );
			}
		}
		fprintf( f, "]" );
	}
	fprintf( f, ",\"meta\":{" );
	fprintf( f, "\"source\":\"cpp::boost\"," );
	fprintf( f, "\"function\":\"boost::math::log1p\"," );
	fprintf( f, "\"implementation\":\"std::log1p (the C library's), after Boost's own domain and pole checks\"," );
	fprintf( f, "\"versions\":{\"boost\":\"%d.%d.%d\"},", BOOST_VERSION / 100000, BOOST_VERSION / 100 % 1000, BOOST_VERSION % 100 );
	fprintf( f, "\"platform\":{" );
#if defined( __linux__ )
	fprintf( f, "\"os\":\"linux\"," );
#elif defined( __APPLE__ )
	fprintf( f, "\"os\":\"darwin\"," );
#else
	fprintf( f, "\"os\":null," );
#endif
#if defined( __x86_64__ )
	fprintf( f, "\"arch\":\"x86_64\"," );
#elif defined( __aarch64__ )
	fprintf( f, "\"arch\":\"aarch64\"," );
#else
	fprintf( f, "\"arch\":null," );
#endif
#if defined( __clang__ )
	fprintf( f, "\"compiler\":\"clang %s, __cplusplus %ld, LDBL_MANT_DIG %d\",", __clang_version__, (long)__cplusplus, LDBL_MANT_DIG );
#elif defined( __GNUC__ )
	fprintf( f, "\"compiler\":\"gcc %s, __cplusplus %ld, LDBL_MANT_DIG %d\",", __VERSION__, (long)__cplusplus, LDBL_MANT_DIG );
#else
	fprintf( f, "\"compiler\":null," );
#endif
#ifdef __GLIBC__
	fprintf( f, "\"libc\":\"glibc %s\"},", gnu_get_libc_version() );
#else
	fprintf( f, "\"libc\":null}," );
#endif
	fprintf( f, "\"generated\":\"%s\",", ts );
	fprintf( f, "\"inputs\":\"%s\",", sha256( (const unsigned char *)bytes.data(), bytes.size() ).c_str() );
	fprintf( f, "\"regime\":\"%s\"}}\n", regime.c_str() );
	fclose( f );
}

/**
* Main execution sequence.
*/
int main( void ) {
	std::vector<std::string> names;
	struct dirent *entry;
	std::string name;
	size_t i;
	DIR *dir;

	dir = opendir( INPUTS );
	if ( dir == NULL ) {
		fprintf( stderr, "unable to open %s\n", INPUTS );
		return 1;
	}
	while ( ( entry = readdir( dir ) ) != NULL ) {
		name = entry->d_name;
		if ( name.size() > 5 && name.compare( name.size()-5, 5, ".json" ) == 0 ) {
			names.push_back( name );
		}
	}
	closedir( dir );
	std::sort( names.begin(), names.end() );
	for ( i = 0; i < names.size(); i++ ) {
		gen( names[ i ] );
	}
	return 0;
}
